                                /** @description Position of the Signal in the request (0-based) */
                                index: number;
                                /** @enum {string} */
                                outcome: "added" | "already_present" | "not_found" | "refused" | "failed" | "not_reached";
                                /** @description Your identifier, as sent */
                                externalId?: string;
