                        /** @description Email address */
                        email?: string;
                        /** @description First name */
                        firstName?: string;
                        /** @description Last name */
                        lastName?: string;
                        /** @description Company domain (e.g. acme.com) */
                        companyDomain?: string;
                        /** @description Company name (alternative to domain) */
                        companyName?: string;
